"""Compute a native unsigned arithmetic expression with power-of-two modulo."""

from collections import Counter
from random import Random

import flagquantum as fq
from flagquantum import synth
from flagquantum.synth import Output, QNum, qfunc


@qfunc
def main(a: Output[QNum], b: Output[QNum], c: Output[QNum], res: Output[QNum]) -> None:
    a |= 2
    b |= 1
    c |= 5
    res |= (((((a + b + c) & 15) % 8) ^ (3 & a)) ^ 10) == 4


def build_program() -> synth.Program:
    return synth.synthesize(main)


def run_example() -> None:
    program = build_program()
    result = fq.run(program)
    probabilities = dict(
        program.probabilities(result, registers=("a", "b", "c", "res"))
    )
    counts = Counter(
        Random(17).choices(
            list(probabilities), weights=list(probabilities.values()), k=1000
        )
    )
    print(dict(counts))


if __name__ == "__main__":
    run_example()

"""Independently prepare the classical source inputs and calculated result."""

import torch

import flagquantum as fq
from examples.synthesis.compare_states import compare_states
from examples.synthesis.functions.arithmetic.arithmetic_expression.arithmetic_expression_example.main import (
    build_program,
)


def reference_circuit() -> fq.Circuit:
    reference = fq.Circuit(7, dtype=torch.complex128)
    for wire in (0, 2, 3, 5):
        reference.x(wire)
    return reference


def run_example() -> None:
    compare_states(build_program(), reference_circuit(), ("a", "b", "c", "res"))


if __name__ == "__main__":
    run_example()
